<script setup lang="ts">
import type { QuoteLine } from '~/types/product';
defineProps<{open:boolean;items:QuoteLine[]}>(); defineEmits<{close:[];remove:[id:string];quantity:[id:string,n:number];copy:[]}>();
const money=(n:number)=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(n);
</script>
<template><Teleport to="body"><div v-if="open" class="backdrop" @click.self="$emit('close')"><aside class="drawer" role="dialog" aria-modal="true" aria-label="Danh sách báo giá"><header><div><small>YOUR QUOTE LIST</small><h2>Danh sách báo giá <i>({{items.length}})</i></h2></div><button class="close" aria-label="Đóng" @click="$emit('close')">×</button></header><div v-if="items.length" class="quote-lines"><article v-for="line in items" :key="line.product.id"><div class="mini-art" :class="'art-'+line.product.visual"><span class="art-shape"></span></div><div class="line-info"><small>{{line.product.category}}</small><h3>{{line.product.name}}</h3><b>{{money(line.product.priceFrom)}} / {{line.product.unit}}</b><div class="qty"><button :disabled="line.quantity<=line.product.minOrder" @click="$emit('quantity',line.product.id,line.quantity-1)">−</button><span>{{line.quantity.toLocaleString('vi-VN')}} {{line.product.unit}}</span><button @click="$emit('quantity',line.product.id,line.quantity+1)">＋</button></div></div><button class="remove" :aria-label="'Xóa '+line.product.name" @click="$emit('remove',line.product.id)">×</button></article></div><div v-else class="empty"><span>＋</span><h3>Danh sách còn trống</h3><p>Thêm sản phẩm bạn quan tâm để chuẩn bị yêu cầu báo giá.</p><button class="primary" @click="$emit('close')">Xem sản phẩm</button></div><footer v-if="items.length"><p>Danh sách tạm thời ở trình duyệt, chưa gửi đến máy chủ.</p><button class="primary full" @click="$emit('copy')">▣ Sao chép yêu cầu báo giá</button></footer></aside></div></Teleport></template>